sealed class Outcome250 {
    data class Success(val payload: String) : Outcome250()
    data object Failure : Outcome250()
}

fun describe250(outcome: Outcome250): String = when (outcome) {
    is Outcome250.Success -> outcome.payload
    Outcome250.Failure -> "failed"
}
fun <T, R> List<T>.mapChecked251(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
fun <T> List<T>.secondOrNull252(): T? = if (size > 1) this[1] else null

fun render252(values: List<String>?): String {
    return values?.filter { it.isNotBlank() }?.joinToString(separator = ",") ?: "empty"
}
